X=$(git ls-files --others --exclude-standard | grep -vxF -e telegram/post_examples_test.go || true); [ -z "$X" ] || { echo "files left in the tree: $X"; exit 1; }
) > $L 2>&1; rc=$?; cat $L; exit $rc

